local LanceMaker = {}
local PRODUCTS = {
    wooden_lance = { name = "Lesena sulica", woodCost = 3, time = 2, cost = 30, attack = 10, durability = 22, description = "Preprosta lesena sulica za turnir." },
    iron_tip_lance = { name = "Železnokljuna sulica", woodCost = 3, ironCost = 1, time = 4, cost = 80, attack = 16, durability = 30, prestige = 1, description = "Sulica z železno konico." },
    steel_tip_lance = { name = "Jeklenokljuna sulica", woodCost = 3, steelCost = 1, time = 6, cost = 200, attack = 22, durability = 40, prestige = 3, happiness = 1, description = "Sulica z jekleno konico za viteze." },
    silver_tip_lance = { name = "Srebrnokljuna sulica", woodCost = 3, steelCost = 1, silverCost = 1, time = 8, cost = 480, attack = 28, durability = 50, prestige = 7, happiness = 2, description = "Sulica s srebrno konico za plemiče." },
    gold_inlaid_lance = { name = "Zlatorobna sulica", woodCost = 4, steelCost = 1, goldCost = 1, silverCost = 1, time = 11, cost = 1100, attack = 35, durability = 65, prestige = 16, happiness = 4, description = "Sulica z zlatorobnim okovjem za turnirje." },
    royal_tournament_lance = { name = "Kraljevska turnirska sulica", woodCost = 5, steelCost = 2, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, time = 16, cost = 2400, attack = 50, durability = 90, prestige = 55, happiness = 11, description = "Velika kraljevska turnirska sulica z zlatim in bisernim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Suličarska delavnica", cost = { gold = 270, wood = 150 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Suličarska kovačija", cost = { gold = 850, wood = 220, stone = 200, iron = 6 }, upkeep = 20, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 1800, wood = 280, stone = 400, silver = 25, steel = 8 }, upkeep = 42, qualityBonus = 30 },
    royal_lance_atelier = { name = "Kraljevski atelje sulic", cost = { gold = 7000, wood = 500, stone = 700, gold = 50, jewel = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 30 },
}
LanceMaker.woodStock = 18; LanceMaker.ironStock = 10; LanceMaker.steelStock = 10; LanceMaker.silverStock = 6; LanceMaker.goldStock = 6; LanceMaker.jewelStock = 6; LanceMaker.pearlStock = 4
LanceMaker.productStock = {}; LanceMaker.buildings = {}; LanceMaker.maker = nil; LanceMaker.activeMaking = {}; LanceMaker.totalProducts = 0; LanceMaker.dayTimer = 0
function LanceMaker.init() LanceMaker.woodStock=18; LanceMaker.ironStock=10; LanceMaker.steelStock=10; LanceMaker.silverStock=6; LanceMaker.goldStock=6; LanceMaker.jewelStock=6; LanceMaker.pearlStock=4; LanceMaker.productStock={}; LanceMaker.buildings={}; LanceMaker.maker=nil; LanceMaker.activeMaking={}; LanceMaker.totalProducts=0; LanceMaker.dayTimer=0; print("[LanceMaker] Royal Lance Maker System initialized (6 products, 4 buildings)") end
function LanceMaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LanceMaker.maker={name=n or ("Suličar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Suličar najet: %s (spretnost: %d)",LanceMaker.maker.name,s),"success") end; return true end
function LanceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LanceMaker.build(id) local ok,e=LanceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LanceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LanceMaker.getQualityBonus() local b=0; for _,bd in ipairs(LanceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LanceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and LanceMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and LanceMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and LanceMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and LanceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LanceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LanceMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LanceMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LanceMaker.buildings==0 then return false,"Potrebna delavnica" end; if not LanceMaker.maker then return false,"Potreben suličar" end; return true end
function LanceMaker.make(pt,qty) qty=qty or 1; local ok,e=LanceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then LanceMaker.woodStock=LanceMaker.woodStock-d.woodCost*qty end; if d.ironCost then LanceMaker.ironStock=LanceMaker.ironStock-d.ironCost*qty end; if d.steelCost then LanceMaker.steelStock=LanceMaker.steelStock-d.steelCost*qty end; if d.silverCost then LanceMaker.silverStock=LanceMaker.silverStock-d.silverCost*qty end; if d.goldCost then LanceMaker.goldStock=LanceMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LanceMaker.jewelStock=LanceMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LanceMaker.pearlStock=LanceMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LanceMaker.maker then t=math.max(1,t-math.floor(LanceMaker.maker.skill/12)) end; table.insert(LanceMaker.activeMaking,{id="lance_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LanceMaker.completeMaking(m) local q=1.0+(LanceMaker.getQualityBonus()/100); if LanceMaker.maker then q=q+(LanceMaker.maker.skill/180) end; q=math.min(2.0,q); LanceMaker.productStock[m.productType]=(LanceMaker.productStock[m.productType] or 0)+m.quantity; LanceMaker.totalProducts=LanceMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LanceMaker.maker then LanceMaker.maker.itemsMade=LanceMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then LanceMaker.maker.skill=math.min(100,LanceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sulica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"lance.completed",{productName=m.productName,attack=m.attack,durability=m.durability}) end end
function LanceMaker.update(dt) if not _G.state then return end; LanceMaker.dayTimer=LanceMaker.dayTimer+dt; if LanceMaker.dayTimer>=30 then LanceMaker.dayTimer=0; for i=#LanceMaker.activeMaking,1,-1 do local m=LanceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LanceMaker.completeMaking(m); table.remove(LanceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LanceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LanceMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LanceMaker.getStats() return {woodStock=LanceMaker.woodStock,ironStock=LanceMaker.ironStock,steelStock=LanceMaker.steelStock,silverStock=LanceMaker.silverStock,goldStock=LanceMaker.goldStock,jewelStock=LanceMaker.jewelStock,pearlStock=LanceMaker.pearlStock,productStock=LanceMaker.productStock,numBuildings=#LanceMaker.buildings,hasMaker=LanceMaker.maker~=nil,makerName=LanceMaker.maker and LanceMaker.maker.name or "—",makerSkill=LanceMaker.maker and LanceMaker.maker.skill or 0,activeMaking=#LanceMaker.activeMaking,totalProducts=LanceMaker.totalProducts} end
return LanceMaker
